import{_ as e,c as n,o as t,a4 as a}from"./chunks/framework.ttppV29E.js";const _=JSON.parse('{"title":"Client Credentials","description":"","frontmatter":{},"headers":[],"relativePath":"docs/endpoint-authentication/client-credentials.md","filePath":"docs/endpoint-authentication/client-credentials.md","lastUpdated":1791278387000}'),s={name:"docs/endpoint-authentication/client-credentials.md"},i=a(`<h1 id="client-credentials" tabindex="-1">Client Credentials <a class="header-anchor" href="#client-credentials" aria-label="Permalink to &quot;Client Credentials&quot;">​</a></h1><p>Client Credentials is a secure authentication method recommended for server to server communication. It is useful for background services or automated tasks that operate independently of user sessions.</p><p>The application authenticates with its own credentials (a client ID and client secret). Before calling an AireGlu endpoint, obtain an access token from AireIdentity.</p><p>Example request:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST https://identity.aireinnovate.com/connect/token</span></span>
<span class="line"><span>CONTENT-TYPE application/x-www-form-urlencoded</span></span>
<span class="line"><span>client_id=[MY_CLIENT]&amp;</span></span>
<span class="line"><span>client_secret=[MY_CLIENT_SECRET]&amp;</span></span>
<span class="line"><span>grant_type=client_credentials&amp;</span></span>
<span class="line"><span>tenant_key=[MY_TENANT_ENVIRONMENT_KEY]&amp;</span></span>
<span class="line"><span>scope=AireGluRuntimeApi</span></span></code></pre></div><p>The client must specify the <code>AireGluRuntimeApi</code> scope.</p><p>Include the returned token in the <code>Authorization</code> header as a Bearer token on subsequent requests to the endpoint. Only the Bearer header is supported; form POST is not used for client credentials.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer {ACCESS_TOKEN}</span></span></code></pre></div><p>Cross tenant endpoint invocations are not permitted. The tenant key claim in the token must match the tenant key of the endpoint being invoked.</p><p>This is not the same as <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html">Open ID Connect Bearer Token</a>, which validates user access tokens from a host application rather than application credentials.</p>`,10),o=[i];function c(p,r,l,d,h,u){return t(),n("div",null,o)}const k=e(s,[["render",c]]);export{_ as __pageData,k as default};
